#!/usr/bin/env bash
# Round 394 PERF-13c-ii-a claims (L29 + L56). Run from the loop root. CLAIMS_STORE overrides the store path.
L=$(pwd); S=${CLAIMS_STORE:-/home/runner/czaba-project/store}; C=$S/app/contexts/ArrangementContext.tsx; P=$S/app/lib/arrangement/preview.client.ts; T=$S/app/lib/arrangement/__tests__/library-preview-stream.test.tsx; LP=$S/app/components/arrangement/ArrangementLibraryPreview.tsx; D=$S/docs/implementation/2026/quarter-IV/252-perf-library-preview-stream.md
echo "K1 $(python3 -I -c "import json;g=json.load(open('gates/gate-round-393.json'));print(g['status'],g['commit'][:7])")"
echo "K2 $(git -C $S rev-parse --short HEAD) $(git -C $S status --short --untracked-files=all | wc -l)"
echo "K3 $(cd $S && sha256sum -c $L/b-round-318/protected-sha256.txt 2>/dev/null | grep -c ': OK$')"
echo "K4 $(cd $S && sha256sum -c $L/b-round-393/r394-frozen-sha256.txt 2>/dev/null | grep -vc ': OK$') $(wc -l < b-round-393/r394-frozen-sha256.txt)"
echo "K5 $(python3 -I -c "import json;d=json.load(open('regression-last.json'));print(d['date'],d['round'])")"
echo "K6 $(curl -s -o /dev/null -w '%{http_code}' --max-time 30 http://127.0.0.1:5173/studio-lab)"
echo "K7 $(python3 -I -c "import json;c=json.load(open('c-round-393.json'));print(c['taskStatus'],len(c['bugs']),c['browserVerified'],c['realVerified'])")"
echo "K8 player stall-const $(grep -c 'export const LIBRARY_PREVIEW_STREAM_STALL_MS = 8000;' $P) listeners ended $(grep -c "addEventListener('ended'" $P) error $(grep -c "addEventListener('error'" $P) waiting $(grep -c "addEventListener('waiting'" $P) playing $(grep -c "addEventListener('playing'" $P) progress $(grep -c "addEventListener('progress'" $P) pause $(grep -c "addEventListener('pause'" $P) removes $(grep -c 'removeEventListener(' $P) try $(grep -c 'try {' $P) play-catch $(grep -c 'void Promise.resolve(element.play()).catch(handleError);' $P) audio-element $(grep -c 'new Audio()' $P) to-destination $(grep -c 'source.connect(ctx.destination);' $P)"
echo "K9 provider stream-call $(grep -c 'playLibraryPreviewStream' $C) fallback-ref $(grep -c 'streamFallbackRef' $C) player-create $(grep -c 'previewPlayerRef.current = createLibraryPreviewPlayer(ctx, () => {' $C) fallback-restart $(grep -c 'startLibraryPreviewRef.current(sourceId, atSeconds);' $C) stop-calls-player $(grep -c 'previewPlayerRef.current?.stopLibraryPreview();' $C)"
echo "K10 rows stream-file $(grep -cE "^  it\('PS[0-9]+ " $T) last $(grep -oE "^  it\('PS[0-9]+" $T | tail -1 | cut -c7-) demo-PS15 $(grep -c "PS15" $S/app/data/__tests__/studio-lab-demo.test.ts) describes $(grep -c '^describe(' $T)"
echo "K11 doc252 l4 $(sed -n 4p $D) | headings $(grep -c '^## ' $D) in-progress-docs $(grep -rln 'In Progress (stage' $S/docs/implementation | wc -l)"
echo "K12 SWEEP player users (roots app/** perf/** e2e/**): $(grep -rlE 'createLibraryPreviewPlayer|LibraryPreviewPlayerOptions|LIBRARY_PREVIEW_STREAM_STALL_MS' $S/app $S/perf $S/e2e --include=*.ts --include=*.tsx | sed "s#$S/##" | sort | tr '\n' ' ')"
echo "K13 testids toggle $(grep -c 'data-testid="arrangement-library-preview-toggle"' $LP) wave $(grep -c 'data-testid="arrangement-library-preview-wave"' $LP) exit $(grep -c 'data-testid="arrangement-exit"' $S/app/components/arrangement/StudioWorkspace.tsx) status $(grep -rc 'data-testid="arrangement-status"' $S/app/components/arrangement --include=*.tsx | grep -v ':0' | wc -l)"
echo "K14 premise-head $(python3 -I -c "import json;d=json.load(open('b-round-393/premise/events-head.json'))['rows'];h=d['HOLD-1440x900'];n=d['NORMAL-SEEK-PAUSE-1440x900'];print('hold-toggle',h['toggle'].strip(),'hold-fb',h['fallbackAt'],'hold-dec',len(h['dec']),'pause-toggle',n['toggleAfterConsolePause'].strip())")"
echo "K15 sketch-events $(python3 -I -c "import json;d=json.load(open('b-round-393/sketch-events.json'))['rows'];print(*[(k.split('-')[0]+'@'+k.split('-')[-1],(v.get('fallbackAt'),len(v['dec']),v.get('toggleAfterConsolePause','-').strip())) for k,v in d.items()])")"
echo "K16 sketch-hold $(python3 -I -c "import json;d=json.load(open('b-round-393/sketch-hold.json'))['rows'];print(*[(k,v['fallbackMs'],len(v['liveAfter'])-len(v['liveBefore']),v['dec'],v['starts'],[q['type'] for q in v['reqsAfterClick']],len(v['reqsAfterFallback'])) for k,v in d.items()])")"
echo "K17 mutants $(grep -c ' RED ' b-round-393/mutants/summary.txt) red, $(grep -c SURVIVED b-round-393/mutants/summary.txt) survived, $(tail -1 b-round-393/mutants/summary.txt)"
echo "K18 covering $(grep -E 'Test Files|Tests ' b-round-393/precheck-covering.log | sed 's/\x1b\[[0-9;]*m//g' | tr -s ' ' | tr '\n' ' ') LRS4 $(sed 's/\x1b\[[0-9;]*m//g' b-round-393/precheck-covering.log | grep -oE 'LRS4.* [0-9]+ms' | grep -oE '[0-9]+ms$')"
echo "K19 sketch-sha256 $(sha256sum b-round-393/sketch-394.patch.txt | cut -c1-16)"
echo "K20 $(for f in tasks/round-393.md c-round-393.json c-round-393.md c-round-393/probe.mjs c-round-382/lib.mjs b-round-393/grants-394.txt b-round-393/r394-frozen-sha256.txt b-round-318/protected-sha256.txt b-round-393/premise/events.mjs b-round-393/premise/hold.mjs b-round-393/premise/warm.mjs b-round-393/premise/events-head.json b-round-393/sketch-events.json b-round-393/sketch-hold.json b-round-393/sketch-394.patch.txt b-round-393/mutants/summary.txt b-round-393/mutants/run.py b-round-393/precheck-covering.log a-round-393/covering-files.txt b-round-393/claims-394.sh gates/round-393/review.md; do test -e $f || echo MISSING:$f; done; echo checked)"
